"""
RiskLens AI — Notification Clients (Email + Jira)
External notification integrations for automated escalation.
"""

import asyncio
import aiosmtplib
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
from typing import Optional
from app.core.config import get_settings
from app.core.logger import get_logger

logger = get_logger("infrastructure.notifications")


class EmailClient:
    """Async email client using SMTP."""

    @staticmethod
    async def send_alert_email(
        to_email: str,
        subject: str,
        body_html: str,
    ) -> bool:
        """Send an alert email via SMTP.

        Args:
            to_email: Recipient email address
            subject: Email subject line
            body_html: HTML body content

        Returns:
            True if sent successfully, False otherwise
        """
        settings = get_settings()

        if not settings.smtp_user or not settings.smtp_password:
            logger.warning("SMTP not configured — skipping email", to=to_email)
            return False

        try:
            message = MIMEMultipart("alternative")
            message["From"] = settings.smtp_from
            message["To"] = to_email
            message["Subject"] = subject
            message.attach(MIMEText(body_html, "html"))

            await aiosmtplib.send(
                message,
                hostname=settings.smtp_host,
                port=settings.smtp_port,
                username=settings.smtp_user,
                password=settings.smtp_password,
                start_tls=True,
            )

            logger.info("Alert email sent", to=to_email, subject=subject)
            return True

        except Exception as e:
            logger.error("Failed to send email", to=to_email, error=str(e))
            return False

    @staticmethod
    def build_alert_email_body(alert: dict, assessment: dict) -> str:
        """Build HTML email body for a risk alert."""
        severity = alert.get("severity", "UNKNOWN")
        severity_color = {
            "LOW": "#22c55e",
            "MEDIUM": "#f59e0b",
            "HIGH": "#ef4444",
            "CRITICAL": "#dc2626",
        }.get(severity, "#6b7280")

        rationale = assessment.get("claude_analysis", {}).get("rationale", "No rationale available.")
        actions = assessment.get("claude_analysis", {}).get("recommended_actions", [])
        actions_html = "".join(f"<li>{a}</li>" for a in actions)

        return f"""
        <html>
        <body style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
            <div style="background: {severity_color}; color: white; padding: 16px; border-radius: 8px 8px 0 0;">
                <h2 style="margin: 0;">🚨 Risk Alert: {severity}</h2>
                <p style="margin: 4px 0 0;">{alert.get('title', 'Portfolio Risk Alert')}</p>
            </div>
            <div style="border: 1px solid #e5e7eb; padding: 16px; border-radius: 0 0 8px 8px;">
                <p><strong>Portfolio:</strong> {alert.get('portfolio_id', 'N/A')}</p>
                <p><strong>Summary:</strong> {alert.get('summary', '')}</p>
                <hr>
                <h3>AI Analysis</h3>
                <p>{rationale}</p>
                <h3>Recommended Actions</h3>
                <ul>{actions_html}</ul>
                <hr>
                <p style="color: #6b7280; font-size: 12px;">
                    Generated by RiskLens AI | {alert.get('created_at', 'N/A')}
                </p>
            </div>
        </body>
        </html>
        """


class JiraClient:
    """Jira REST API client for creating risk tickets."""

    @staticmethod
    async def create_ticket(
        summary: str,
        description: str,
        priority: str = "High",
        labels: Optional[list] = None,
    ) -> Optional[str]:
        """Create a Jira ticket for a risk breach.

        Args:
            summary: Ticket summary/title
            description: Detailed description
            priority: Jira priority (Highest, High, Medium, Low)
            labels: Optional list of labels

        Returns:
            Ticket key (e.g., "RISK-3312") or None if failed
        """
        settings = get_settings()

        if not settings.jira_base_url or not settings.jira_api_token:
            logger.warning("Jira not configured — skipping ticket creation")
            return None

        try:
            import httpx

            url = f"{settings.jira_base_url}/rest/api/3/issue"
            headers = {
                "Content-Type": "application/json",
            }
            auth = (settings.jira_email, settings.jira_api_token)

            payload = {
                "fields": {
                    "project": {"key": settings.jira_project_key},
                    "summary": summary,
                    "description": {
                        "type": "doc",
                        "version": 1,
                        "content": [
                            {
                                "type": "paragraph",
                                "content": [{"type": "text", "text": description}],
                            }
                        ],
                    },
                    "issuetype": {"name": "Task"},
                    "priority": {"name": priority},
                    "labels": labels or ["risk-alert", "auto-generated"],
                }
            }

            async with httpx.AsyncClient() as client:
                response = await client.post(url, json=payload, headers=headers, auth=auth)
                response.raise_for_status()
                ticket_key = response.json().get("key", "UNKNOWN")
                logger.info("Jira ticket created", ticket_key=ticket_key)
                return ticket_key

        except Exception as e:
            logger.error("Failed to create Jira ticket", error=str(e))
            return None
